SELECT FROM book b JOIN book_category c ON c.id = b.category_id AND c.deleted = 0 WHERE b.deleted = 0
AND (b.title LIKE CONCAT('%', #{query.keyword}, '%') OR b.isbn LIKE CONCAT('%', #{query.keyword}, '%') OR b.author LIKE CONCAT('%', #{query.keyword}, '%'))
AND b.category_id = #{query.categoryId}
AND b.status = #{query.status}
ORDER BY b.id DESC
